"""
PyPI mirror probing (latency + package throughput) and resumable wheel downloads.

Index latency alone often ranks Aliyun first while large .whl transfers stall;
throughput samples on a real packages/ URL fix ordering, and resumable HTTP
downloads avoid pip's fragile long transfers.
"""

from __future__ import annotations

import logging
import os
import re
import time
import urllib.error
import urllib.request
from pathlib import Path
from typing import Any, Callable, Sequence
from urllib.parse import urlparse

ProgressCb = Callable[[dict[str, Any]], None]
_log = logging.getLogger("transub_engine.pip_mirror_util")

