PIP_MIRRORS = (ALIYUN_PIP, HUAWEI_PIP, TSINGHUA_PIP, PYPI_OFFICIAL)

# Hosts that returned HTTP 403/Forbidden (or similar) on wheel download in this
# process. Index probe can still look healthy while files are blocked.
_demoted_mirror_hosts: set[str] = set()

_RE_MIRROR_HTTP_DENY = re.compile(
    r"(?:HTTP\s*error\s*403|403\s*Client\s*Error|Forbidden\s+for\s+url|"
    r"HTTP\s*error\s*404|404\s*Client\s*Error|"
    r"Access\s+Denied|Could\s+not\s+install\s+requirement[^\n]*HTTP\s+error|"
    r"STALL:|下载停滞)",
    re.I,
)

