class MirrorStallError(RuntimeError):
    """Raised when a mirror transfer makes no progress for too long."""


class MirrorTooSlowError(MirrorStallError):
    """Raised when a mirror transfers data but far too slowly to finish in time."""


def transfer_should_abort(
    *,
    elapsed_sec: float,
    session_bytes: int,
    last_progress_age_sec: float,
    stall_sec: float = DOWNLOAD_STALL_SEC,
    min_bps: float = DOWNLOAD_MIN_BPS,
    warmup_sec: float = DOWNLOAD_SLOW_WARMUP_SEC,
    max_sec: float = DOWNLOAD_MIRROR_MAX_SEC,
    slow_min_bytes: int = DOWNLOAD_SLOW_MIN_BYTES,
) -> str | None:
    """
    Return an abort reason, or None if the transfer may continue.

    Distinguishes hard stall (no new bytes) from trickle that would burn ~30 min.
    """
    if elapsed_sec >= max_sec:
        return f"STALL: 单镜像超过 {int(max_sec)} 秒上限"
    if last_progress_age_sec >= stall_sec:
        return f"STALL: 下载停滞超过 {int(stall_sec)} 秒"
    if (
        elapsed_sec >= warmup_sec
        and session_bytes >= slow_min_bytes
        and session_bytes / max(elapsed_sec, 0.001) < min_bps
    ):
        bps = session_bytes / max(elapsed_sec, 0.001)
        return (
            f"STALL: 下载过慢（约 {bps / 1024:.0f} KB/s < {min_bps / 1024:.0f} KB/s），切换镜像"
        )
    return None


def is_mirror_http_deny(text: str) -> bool:
    """True when pip/download output looks like HTTP deny or stall."""
    return bool(_RE_MIRROR_HTTP_DENY.search(str(text or "")))


def note_mirror_denied(host: str) -> None:
    h = str(host or "").strip().lower()
    if h:
        _demoted_mirror_hosts.add(h)


def clear_demoted_mirrors() -> None:
    _demoted_mirror_hosts.clear()


def demoted_mirror_hosts() -> frozenset[str]:
    return frozenset(_demoted_mirror_hosts)


def packages_base_url(index_url: str) -> str:
    """Map a PyPI simple index URL to its packages/ file root."""
    u = str(index_url or "").strip().rstrip("/")
    host = (urlparse(u).hostname or "").lower()
    if host in ("pypi.org", "pypi.python.org") or u.endswith("://pypi.org/simple"):
        return "https://files.pythonhosted.org/packages"
    if u.endswith("/simple"):
        return u[: -len("/simple")] + "/packages"
    return u + "/packages"


def wheel_url_for(index_url: str, rel_path: str) -> str:
    base = packages_base_url(index_url).rstrip("/")
    rel = str(rel_path or "").lstrip("/")
    return f"{base}/{rel}"


def known_wheel_rel(package_name: str) -> str:
    key = str(package_name or "").strip().lower().replace("_", "-")
    return KNOWN_WHEEL_RELS.get(key, "")


def wheel_cache_dir() -> Path:
    try:
        from .paths import get_data_root

        root = get_data_root() / "wheel-cache"
    except Exception:
        root = Path(os.environ.get("TEMP") or os.getcwd()) / "TransubWheelCache"
    root.mkdir(parents=True, exist_ok=True)
    return root


def format_bytes_per_sec(bps: float | int | None) -> str:
    try:
        n = float(bps or 0)
    except (TypeError, ValueError):
        n = 0.0
    if n <= 0:
        return ""
    if n >= 1024 * 1024:
        return f"{n / (1024 * 1024):.1f} MB/s"
    if n >= 1024:
        return f"{n / 1024:.0f} KB/s"
    return f"{int(n)} B/s"


def format_probe_summary(probe_rows: Sequence[dict[str, Any]]) -> str:
    parts: list[str] = []
    for row in probe_rows:
        host = str(row.get("host") or "?")
        if not row.get("ok"):
            parts.append(f"{host}: 不可达")
            continue
        bps = format_bytes_per_sec(row.get("bytesPerSec"))
        ms = row.get("latencyMs")
        if bps:
            parts.append(f"{host}: {bps}")
        elif ms is not None:
            parts.append(f"{host}: {ms}ms")
        else:
            parts.append(f"{host}: ok")
    return "；".join(parts)


def _probe_index_latency(index_url: str, *, timeout: float) -> tuple[bool, float, int, str]:
    url = str(index_url or "").rstrip("/") + "/"
    t0 = time.perf_counter()
    try:
        req = urllib.request.Request(
            url,
            headers={"User-Agent": "transub-engine-mirror-probe"},
            method="GET",
        )
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            chunk = resp.read(8192)
        ms = (time.perf_counter() - t0) * 1000.0
        return True, ms, len(chunk or b""), ""
    except (urllib.error.URLError, TimeoutError, OSError) as err:
        ms = (time.perf_counter() - t0) * 1000.0
        return False, ms, 0, str(err)[:240]
    except Exception as err:  # noqa: BLE001
        ms = (time.perf_counter() - t0) * 1000.0
        return False, ms, 0, str(err)[:240]


def _probe_package_throughput(
    index_url: str,
    *,
    timeout: float,
    sample_bytes: int,
) -> tuple[bool, float, int, float, str]:
    """
    Range-GET a known wheel path; return ok, latencyMs, sampleBytes, bytesPerSec, error.
    """
    url = wheel_url_for(index_url, PROBE_WHEEL_REL)
    t0 = time.perf_counter()
    try:
        req = urllib.request.Request(
            url,
            headers={
                "User-Agent": "transub-engine-mirror-probe",
                "Range": f"bytes=0-{max(0, sample_bytes - 1)}",
                "Accept": "*/*",
            },
            method="GET",
        )
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            status = getattr(resp, "status", None) or resp.getcode()
            if status not in (200, 206):
                ms = (time.perf_counter() - t0) * 1000.0
                return False, ms, 0, 0.0, f"HTTP {status}"
            got = 0
            target = max(1024, int(sample_bytes))
            while got < target:
                chunk = resp.read(min(65536, target - got))
                if not chunk:
                    break
                got += len(chunk)
        ms = max(1.0, (time.perf_counter() - t0) * 1000.0)
        bps = (got / (ms / 1000.0)) if got > 0 else 0.0
        return got > 0, ms, got, round(bps, 1), ""
    except (urllib.error.URLError, TimeoutError, OSError) as err:
        ms = (time.perf_counter() - t0) * 1000.0
        return False, ms, 0, 0.0, str(err)[:240]
    except Exception as err:  # noqa: BLE001
        ms = (time.perf_counter() - t0) * 1000.0
        return False, ms, 0, 0.0, str(err)[:240]


def probe_pip_mirrors(
    mirrors: Sequence[tuple[str, str]] | None = None,
    *,
    timeout: float = PROBE_TIMEOUT_SEC,
    sample_bytes: int = PROBE_SAMPLE_BYTES,
) -> list[dict[str, Any]]:
    """
    Rank mirrors by package-file throughput (primary) and index latency (fallback).

    Each row: ok, indexUrl, host, latencyMs, bytesPerSec, sampleBytes, error?
    """
    targets = list(mirrors) if mirrors is not None else list(PIP_MIRRORS)
    out: list[dict[str, Any]] = []
    for index_url, host in targets:
        item: dict[str, Any] = {
            "ok": False,
            "indexUrl": index_url,
            "host": host,
            "latencyMs": None,
            "bytesPerSec": 0,
            "sampleBytes": 0,
        }
        idx_ok, idx_ms, _idx_n, idx_err = _probe_index_latency(index_url, timeout=timeout)
        item["latencyMs"] = round(idx_ms, 1)
        thr_ok, thr_ms, thr_n, thr_bps, thr_err = _probe_package_throughput(
            index_url,
            timeout=timeout,
            sample_bytes=sample_bytes,
        )
        if thr_ok:
            item.update(
                {
                    "ok": True,
                    "latencyMs": round(min(idx_ms, thr_ms) if idx_ok else thr_ms, 1),
                    "bytesPerSec": thr_bps,
                    "sampleBytes": thr_n,
                }
            )
        elif idx_ok:
            # Index reachable but package sample failed (404 / block) — still usable
            # for pip -i, but rank below throughput winners.
            item.update(
                {
                    "ok": True,
                    "bytesPerSec": 0,
                    "sampleBytes": 0,
                    "error": thr_err or idx_err,
                }
            )
        else:
            item["error"] = thr_err or idx_err or "unreachable"
        out.append(item)
    return out


def order_pip_mirrors(
    probe_results: Sequence[dict[str, Any]] | None = None,
    *,
    mirrors: Sequence[tuple[str, str]] | None = None,
) -> list[tuple[str, str]]:
    """Sort mirrors: demoted last, reachable first, then higher throughput, then lower latency."""
    results = list(probe_results) if probe_results is not None else probe_pip_mirrors(mirrors)
    demoted = {h.lower() for h in _demoted_mirror_hosts}
    ranked = sorted(
        results,
        key=lambda r: (
            1 if str(r.get("host") or "").strip().lower() in demoted else 0,
            0 if r.get("ok") else 1,
            # Higher throughput first (negate).
            -float(r.get("bytesPerSec") or 0),
            float(r["latencyMs"]) if r.get("latencyMs") is not None else 1e12,
            str(r.get("host") or ""),
        ),
    )
    ordered: list[tuple[str, str]] = []
    seen: set[str] = set()
    for row in ranked:
        index_url = str(row.get("indexUrl") or "").strip()
        host = str(row.get("host") or "").strip()
        if not index_url or not host or index_url in seen:
            continue
        seen.add(index_url)
        ordered.append((index_url, host))
    for index_url, host in mirrors or PIP_MIRRORS:
        if index_url not in seen:
            ordered.append((index_url, host))
            seen.add(index_url)
    return ordered or list(mirrors or PIP_MIRRORS)


def best_probe_bytes_per_sec(probe_rows: Sequence[dict[str, Any]]) -> float:
    best = 0.0
    for row in probe_rows or []:
        if not row.get("ok"):
            continue
        try:
            best = max(best, float(row.get("bytesPerSec") or 0))
        except (TypeError, ValueError):
            continue
    return best


def install_local_wheel_files(
    wheel_paths: Sequence[str],
    *,
    on_progress: ProgressCb | None = None,
    detail_prefix: str = "本地安装",
    timeout_sec: float = 1800.0,
) -> dict[str, Any]:
    """
    Install already-downloaded .whl files with **no network** (``--no-index --no-deps``).

    Using ``pip install --upgrade <paths>`` without ``--no-index`` makes pip contact
    PyPI mirrors again and routinely hangs 10+ minutes after a successful download.
    """
    import subprocess
    import sys
    import threading

    paths = [str(p) for p in wheel_paths if str(p).strip()]
    paths = [p for p in paths if Path(p).is_file()]
    if not paths:
        return {"ok": False, "error": "没有可安装的本地 .whl 文件"}

    def emit(payload: dict[str, Any]) -> None:
        if on_progress:
            try:
                on_progress(payload)
            except Exception:
                pass

    names = [Path(p).name for p in paths]
    short = ", ".join(names[:3]) + ("…" if len(names) > 3 else "")
    emit(
        {
            "type": "progress",
            "stage": "install",
            "percent": 78,
            "detail": f"{detail_prefix}（离线，{len(paths)} 个包：{short}）…",
            "downloadedBytes": None,
            "totalBytes": None,
            "bytesPerSecond": 0,
        }
    )

    cmd = [
        sys.executable,
        "-u",
        "-m",
        "pip",
        "install",
        "--force-reinstall",
        "--no-deps",
        "--no-index",
        "--no-cache-dir",
        "--disable-pip-version-check",
        *paths,
    ]
    _log.info("install_local_wheel_files: %s", " ".join(cmd))
    env = os.environ.copy()
    env["PYTHONUNBUFFERED"] = "1"
    # Ensure pip cannot pick up a user index URL / proxy that reintroduces network waits.
    env.pop("PIP_INDEX_URL", None)
    env.pop("PIP_EXTRA_INDEX_URL", None)
    env["PIP_NO_INDEX"] = "1"

    try:
        proc = subprocess.Popen(
            cmd,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            text=True,
            encoding="utf-8",
            errors="replace",
            env=env,
            bufsize=1,
        )
    except OSError as err:
        return {"ok": False, "error": str(err)}

    chunks: list[str] = []
    started = time.monotonic()
    stop_hb = threading.Event()

    def _hb() -> None:
        while not stop_hb.wait(2.0):
            elapsed = int(time.monotonic() - started)
            emit(
                {
                    "type": "progress",
                    "stage": "install",
                    "percent": min(95, 78 + elapsed // 8),
                    "detail": f"{detail_prefix}解压写入中…（已 {elapsed} 秒，大包可能需数分钟）",
                }
            )

    hb = threading.Thread(target=_hb, name="local-whl-install-hb", daemon=True)
    hb.start()
    try:
        assert proc.stdout is not None
        while True:
            if timeout_sec > 0 and (time.monotonic() - started) > timeout_sec:
                try:
                    proc.kill()
                except Exception:
                    pass
                return {
                    "ok": False,
                    "error": f"本地安装超时（{int(timeout_sec)} 秒）。wheel 已在缓存，可重试或改用手动安装。",
                    "logTail": "".join(chunks)[-1200:],
                }
            line = proc.stdout.readline()
            if not line:
                break
            text = line.strip()
            if text:
                chunks.append(text + "\n")
                if len(chunks) > 120:
                    chunks = chunks[-80:]
                low = text.lower()
                if "installing" in low or "processing" in low or ".whl" in low:
                    emit(
                        {
                            "type": "progress",
                            "stage": "install",
                            "percent": min(94, 80 + int((time.monotonic() - started) / 6)),
                            "detail": f"{detail_prefix}：{text[:100]}",
                        }
                    )
        code = proc.wait(timeout=60)
    except Exception as err:
        try:
            proc.kill()
        except Exception:
            pass
        return {"ok": False, "error": str(err), "logTail": "".join(chunks)[-1200:]}
    finally:
        stop_hb.set()
        try:
            hb.join(timeout=1.0)
        except Exception:
            pass

    log_tail = "".join(chunks)[-1200:]
    if code == 0:
        emit(
            {
                "type": "progress",
                "stage": "install",
                "percent": 96,
                "detail": f"{detail_prefix}完成",
            }
        )
        return {"ok": True, "logTail": log_tail, "paths": paths}
    low = log_tail.lower()
    # Parent process often already imported native wheels; Windows then denies
    # overwrite (WinError 5) during --force-reinstall.
    if "winerror 5" in low or "拒绝访问" in log_tail or "access is denied" in low:
        return {
            "ok": False,
            "code": "EXTRAS_LOCKED_IN_PROCESS",
            "error": (
                f"本地 pip 安装失败（exit {code}）：文件被占用/拒绝访问。"
                "请先停止引擎后再重试，或改用手动安装。"
            ),
            "logTail": log_tail,
        }
    err_line = ""
    for line in reversed(log_tail.splitlines()):
        s = line.strip()
        if not s:
            continue
        if s.lower().startswith("error") or "winerror" in s.lower() or "拒绝访问" in s:
            err_line = s[:240]
            break
    detail = f"：{err_line}" if err_line else ""
    return {
        "ok": False,
        "error": f"本地 pip 安装失败（exit {code}）{detail}",
        "logTail": log_tail,
    }


def download_url_resumable(
    url: str,
    dest: Path,
    *,
    on_progress: ProgressCb | None = None,
    host: str = "",
    detail_prefix: str = "",
    stall_sec: float = DOWNLOAD_STALL_SEC,
    timeout: float = 30.0,
    expected_total: int | None = None,
    max_sec: float = DOWNLOAD_MIRROR_MAX_SEC,
    min_bps: float = DOWNLOAD_MIN_BPS,
) -> dict[str, Any]:
    """
    Download ``url`` to ``dest`` with Range resume and stall / too-slow detection.

    Partial bytes live in ``dest.with_suffix(dest.suffix + '.part')``.
    """
    dest = Path(dest)
    dest.parent.mkdir(parents=True, exist_ok=True)
    part = dest.with_suffix(dest.suffix + ".part")
    if dest.is_file() and dest.stat().st_size > 1024 and not part.exists():
        return {"ok": True, "path": str(dest), "skipped": True, "bytes": dest.stat().st_size}

    existing = part.stat().st_size if part.is_file() else 0
    headers = {
        "User-Agent": "transub-engine-wheel-dl",
        "Accept": "*/*",
    }
    if existing > 0:
        headers["Range"] = f"bytes={existing}-"

    def emit(payload: dict[str, Any]) -> None:
        if on_progress:
            try:
                on_progress(payload)
            except Exception:
                pass

    t0 = time.monotonic()
    last_data_at = t0
    written = existing
    total = int(expected_total or 0)
    session_start_bytes = existing

    try:
        req = urllib.request.Request(str(url), headers=headers, method="GET")
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            status = getattr(resp, "status", None) or resp.getcode()
            if status == 200 and existing > 0:
                # Server ignored Range — restart.
                existing = 0
                written = 0
                session_start_bytes = 0
                try:
                    part.unlink(missing_ok=True)  # type: ignore[call-arg]
                except TypeError:
                    if part.exists():
                        part.unlink()
                except OSError:
                    pass
            elif status not in (200, 206):
                raise urllib.error.HTTPError(url, status, f"HTTP {status}", resp.headers, None)

            cl = resp.headers.get("Content-Length")
            cr = resp.headers.get("Content-Range") or ""
            if cr.startswith("bytes ") and "/" in cr:
                try:
                    total = int(cr.rsplit("/", 1)[-1])
                except ValueError:
                    pass
            elif cl and status == 206:
                try:
                    total = existing + int(cl)
                except ValueError:
                    pass
            elif cl and status == 200:
                try:
                    total = int(cl)
                except ValueError:
                    pass

            mode = "ab" if existing > 0 and status == 206 else "wb"
            if mode == "wb":
                written = 0
                session_start_bytes = 0
            last_emit = 0.0
            with open(part, mode) as fh:
                while True:
                    now = time.monotonic()
                    session_bytes = max(0, written - session_start_bytes)
                    reason = transfer_should_abort(
                        elapsed_sec=now - t0,
                        session_bytes=session_bytes,
                        last_progress_age_sec=now - last_data_at,
                        stall_sec=stall_sec,
                        min_bps=min_bps,
                        max_sec=max_sec,
                    )
                    if reason:
                        raise MirrorTooSlowError(f"{reason}（{host or url}）")
                    try:
                        # Smaller chunks so we re-check stall/speed often.
                        chunk = resp.read(64 * 1024)
                    except TimeoutError as err:
                        raise MirrorStallError(
                            f"STALL: 读取超时（{host or url}）: {err}"
                        ) from err
                    except OSError as err:
                        raise MirrorStallError(
                            f"STALL: 连接中断（{host or url}）: {err}"
                        ) from err
                    if not chunk:
                        break
                    fh.write(chunk)
                    written += len(chunk)
                    last_data_at = time.monotonic()
                    now = time.monotonic()
                    if now - last_emit >= 0.4:
                        last_emit = now
                        elapsed = max(0.001, now - t0)
                        session = max(0, written - session_start_bytes)
                        speed = session / elapsed
                        prefix = detail_prefix or "下载运行库"
                        name = dest.name
                        if len(name) > 42:
                            name = name[:39] + "…"
                        emit(
                            {
                                "type": "progress",
                                "stage": "download",
                                "detail": f"{prefix}（{host}）· {name}",
                                "mirror": host,
                                "downloadedBytes": int(written),
                                "totalBytes": int(total) if total > 0 else None,
                                "bytesPerSecond": round(speed, 1),
                                "suggestManual": bool(
                                    speed > 0 and speed < 80_000 and written > 2 * 1024 * 1024
                                ),
                            }
                        )
    except MirrorStallError:
        raise
    except urllib.error.HTTPError as err:
        return {"ok": False, "error": f"HTTP {err.code}", "path": str(part), "bytes": written}
    except (urllib.error.URLError, TimeoutError, OSError) as err:
        return {"ok": False, "error": str(err)[:400], "path": str(part), "bytes": written}

    if written <= 0:
        return {"ok": False, "error": "empty download", "path": str(part), "bytes": 0}
    if total > 0 and written < total:
        return {
            "ok": False,
            "error": f"incomplete {written}/{total}",
            "path": str(part),
            "bytes": written,
        }

    try:
        if dest.exists():
            dest.unlink()
    except OSError:
        pass
    part.replace(dest)
    return {"ok": True, "path": str(dest), "bytes": written, "host": host}


def download_known_wheels(
    package_names: Sequence[str],
    *,
    index_url: str,
    host: str,
    on_progress: ProgressCb | None = None,
    detail_prefix: str = "下载运行库",
    stall_sec: float = DOWNLOAD_STALL_SEC,
) -> dict[str, Any]:
    """
    Download known-hash wheels for ``package_names`` from one mirror into wheel-cache.

    Returns ok + localPaths, or ok=False with error (caller should try next mirror).
    """
    cache = wheel_cache_dir()
    paths: list[str] = []
    missing: list[str] = []
    for raw in package_names:
        name = str(raw or "").strip().lower().replace("_", "-")
        # Strip version pins: "numpy>=1.24" → try "numpy"
        base = name.split(">", 1)[0].split("<", 1)[0].split("=", 1)[0].split("[", 1)[0].strip()
        rel = known_wheel_rel(base)
        if not rel:
            missing.append(base or name)
            continue
        filename = rel.rsplit("/", 1)[-1]
        dest = cache / filename
        url = wheel_url_for(index_url, rel)
        try:
            result = download_url_resumable(
                url,
                dest,
                on_progress=on_progress,
                host=host,
                detail_prefix=detail_prefix,
                stall_sec=stall_sec,
            )
        except MirrorStallError as err:
            note_mirror_denied(host)  # soft demote for this process? skip — stall ≠ 403
            return {
                "ok": False,
                "stalled": True,
                "error": str(err),
                "host": host,
                "localPaths": paths,
            }
        if not result.get("ok"):
            return {
                "ok": False,
                "error": result.get("error") or "download failed",
                "host": host,
                "localPaths": paths,
                "package": base,
            }
        paths.append(str(result["path"]))

    if missing and not paths:
        return {"ok": False, "error": f"no known wheel URLs for: {', '.join(missing)}", "missing": missing}
    return {
        "ok": True,
        "localPaths": paths,
        "missing": missing,
        "host": host,
    }
